import"./modulepreload-polyfill-B5Qt9EMX.js";async function i(){try{const t=await fetch("http://localhost:3000/api/health");if(!t.ok)throw new Error("O servidor retornou um erro.");const o=await t.json();console.log(o.message)}catch(t){console.error("Não foi possível conectar ao servidor:",t)}}i();const n=document.querySelector("#contact-form"),e=document.querySelector("#form-feedback");n.addEventListener("submit",async t=>{t.preventDefault();const o=n.querySelector('button[type="submit"]'),s=new FormData(n),c=Object.fromEntries(s.entries());o.disabled=!0,o.textContent="Enviando...",e.textContent="";try{const r=await fetch("http://localhost:3000/api/contatos",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(c)}),a=await r.json();if(!r.ok)throw new Error(a.message);e.textContent=a.message,e.style.color="#087f5b",n.reset()}catch(r){e.textContent=r.message||"Não foi possível enviar a solicitação.",e.style.color="#c92a2a"}finally{o.disabled=!1,o.textContent="Enviar solicitação"}});
